import process from 'node:process';
import { logger } from '@lightproject/common/logger';

import { build } from './autogen/index';

// Main execution when run directly
if (import.meta.url === `file://${process.argv[1]}`) {
  (async () => {
    try {
      await build();
    } catch (error) {
      logger.error('Error in autogen script:', error);
      process.exit(1);
    }
  })().catch(error => {
    logger.error('Unhandled error in autogen:', error);
    process.exit(1);
  });
}

// Re-export everything from the modular autogen system
export * from './autogen/index';

import process from 'node:process';
import { endpoints } from '@lightproject/common/configs';
import type { CorsOptions } from 'cors';

const allowedOrigins = [
  endpoints.apiUrl,
  endpoints.siteUrl,
  'http://localhost:3000',
  'http://localhost:3001',
];

if (process.env['SITE_URL']) {
  allowedOrigins.push(process.env['SITE_URL']);
}

const corsOptions: CorsOptions = {
  allowedHeaders: [
    'Origin',
    'X-Requested-With',
    'Accept',
    'Authorization',
    'Content-Type',
  ],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'],
  origin: allowedOrigins,
};

export { allowedOrigins, corsOptions };

