import {
  type ExpressNextFunction,
  type ExpressRequest,
  type ExpressResponse,
  HTTP_STATUS_NOT_FOUND,
} from '../types/middlware';

/**
 * Handles 404 Not Found errors by returning a standard error response.
 * This should be placed after all other routes.
 * 
 * @param req - The Express request object
 * @param res - The Express response object
 * @param next - The Express next function
 */
export const notFoundHandler = (
  req: any,
  res: any,
  next: any
) => {
  const mReq: ExpressRequest = req;
  const mRes: ExpressResponse = res;
  const __mNext: ExpressNextFunction = next;

  mRes.statusCode = HTTP_STATUS_NOT_FOUND;
  const errorResponse = getErrorResponse(
    new Error('Not Found'),
    mReq,
    mRes
  );

  if (!mRes.headersSent) {
    mRes.status(HTTP_STATUS_NOT_FOUND).json(errorResponse);
  }

  if (typeof __mNext === 'function') {
    // Usually not needed for 404 but added for completeness
  }
};

