export const fixFilter = (
  input: null | Readonly<Record<string, unknown>> | undefined
) => {
  return input === undefined || input === null || typeof input !== 'object'
    ? {}
    : {
        ...input,
    orderBy: input['orderBy'] ?? undefined,
    where: input['where'] ?? {},
      };
};

