import { Buffer } from 'node:buffer';
import type { NextFunction, Response } from '../types/middlware';

const isBufferEncoding = (val: unknown): val is BufferEncoding => {
  const encodings: string[] = ['ascii', 'utf8', 'utf16le', 'ucs2', 'base64', 'latin1', 'binary', 'hex'];
  return typeof val === 'string' && encodings.includes(val);
};

export const captureResponse = (_req: any, res: any, next: any): void => {
  const mRes: Response = res;
  const __mNext: NextFunction = next;

  if (mRes.locals['metadata']) {
    mRes.locals['metadata']['source'] = 'captureResponse';
  }

  const originalWrite: any = mRes.write.bind(mRes);
  const originalEnd: any = mRes.end.bind(mRes);
  const originalSend = mRes.send.bind(mRes);

  const chunks: Buffer[] = [];

  mRes.send = (body: any): Response => {
    if (body) {
      if (typeof body === 'string') {
        chunks.push(Buffer.from(body));
      } else if (Buffer.isBuffer(body)) {
        chunks.push(body);
      } else {
        chunks.push(Buffer.from(JSON.stringify(body)));
      }
    }
    return originalSend(body);
  };

  mRes.write = (
    chunk: any,
    encodingOrCallback?: any,
    callback?: any
  ): boolean => {
    if (chunk) {
      if (typeof chunk === 'string') {
        chunks.push(Buffer.from(chunk, isBufferEncoding(encodingOrCallback) ? encodingOrCallback : 'utf8'));
      } else {
        chunks.push(Buffer.from(chunk));
      }
    }
    if (typeof encodingOrCallback === 'function') {
      return originalWrite(chunk, encodingOrCallback);
    }
    return originalWrite(chunk, encodingOrCallback, callback);
  };

  mRes.end = (
    chunk: any,
    encodingOrCallback?: any,
    callback?: any
  ): Response => {
    if (chunk) {
      if (typeof chunk === 'string') {
        chunks.push(Buffer.from(chunk, isBufferEncoding(encodingOrCallback) ? encodingOrCallback : 'utf8'));
      } else {
        chunks.push(Buffer.from(chunk));
      }
    }

    const fullBody = Buffer.concat(chunks).toString('utf8');
    if (mRes.locals['metadata']) {
      mRes.locals['metadata']['responseBody'] = fullBody;
    }

    if (typeof encodingOrCallback === 'function') {
      return originalEnd(chunk, encodingOrCallback);
    }
    return originalEnd(chunk, encodingOrCallback, callback);
  };

  if (typeof __mNext === 'function') {
    __mNext();
  }
};

