import process from 'node:process';
import { endpoints } from '@lightproject/common/configs';
import {
  isCi,
  isLocal,
  isNonProduction,
  isOtherEnvironment,
  isTest,
} from '@lightproject/common/environment';
import { logger } from '@lightproject/common/logger';

import type {
  NextFunction,
  Request,
  Response,
} from '../types/middlware';

import { errorHandler } from './error-handler';

const logDebugTruthTable = (
  isLoopback: boolean,
  inSafeEnv: boolean,
  allowAll: boolean,
  blockAll: boolean,
  isAllowed: boolean
) => {
  if (!isNonProduction() || process.env['DEBUG'] !== 'true') {
    return;
  }

  const bools = [false, true];
  logger.debug('--- trustProxy decision truth table ---');
  for (const loopback of bools) {
    for (const safe of bools) {
      for (const allow of bools) {
        for (const block of bools) {
          const allowedByBlock = !block;
          const allowedByAllow = allow;
          const allowedByEnv = loopback || safe;
          const decision = allowedByBlock && (allowedByAllow || allowedByEnv);
          logger.debug(
            `isLoopback=${loopback}, inSafeEnv=${safe}, allowAll=${allow}, blockAll=${block} => isAllowed=${decision}`
          );
        }
      }
    }
  }
  logger.debug('--- actual flags ---');
  logger.debug(
    `isLoopback=${isLoopback}, inSafeEnv=${inSafeEnv}, allowAll=${allowAll}, blockAll=${blockAll} => isAllowed=${isAllowed}`
  );
};

const handleAccessDenied = (
  req: any,
  res: any,
  next: any
) => {
  const mReq: Request = req;
  const mRes: Response = res;
  const _mNext: NextFunction = next;

  const statusCode = 403;
  const error = {
    message: 'Access denied',
    name: 'AccessDeniedError',
    stack: 'No stack trace available',
    statusCode,
  };

  mRes.status(statusCode);

  if (endpoints.isTrpcEndpoint(mReq.originalUrl)) {
    errorHandler(
      error,
      mReq,
      mRes,
      _mNext
    );
  } else {
    _mNext(error);
  }
};

export const trustProxyMiddleware = (
  req: any,
  res: any,
  next: any
) => {
  const mReq: Request = req;
  const mRes: Response = res;
  const _mNext: NextFunction = next;

  const allowedIps = new Set(['127.0.0.1', '::1']);
  const requestIp = mReq.ip || mReq.socket.remoteAddress;

  const isLoopback = !!requestIp && allowedIps.has(requestIp);
  const inSafeEnv = isLocal() || isTest() || isCi() || isOtherEnvironment();
  const allowAll = process.env['ALLOW_ALL_IPS'] === 'true';
  const blockAll = process.env['BLOCK_ALL_IPS'] === 'true';

  // Precedence: blockAll > allowAll > (isLoopback || inSafeEnv)
  const isAllowed = !blockAll && (allowAll || isLoopback || inSafeEnv);

  logDebugTruthTable(isLoopback, inSafeEnv, allowAll, blockAll, isAllowed);

  if (isAllowed) {
    _mNext();
  } else {
    handleAccessDenied(mReq, mRes, _mNext);
  }
};

import { URL } from 'node:url';
import type { Response } from 'express';
import { endpoints } from '@lightproject/common/configs';
import { logger } from '@lightproject/common/logger';
import { invoker } from '@lightproject/common/utils';
import type { Request, ServiceContext } from '../types/middlware';
import type { RouteInfo } from './autogen/types';

const DEFAULT_SUCCESS_STATUS_CODE = 200;

const isRecord = (val: unknown): val is Record<string, unknown> =>
  typeof val === 'object' && val !== null && !Array.isArray(val);

export const registerHttpRoutes = (
  app: any,
  routes: readonly RouteInfo[],
  rootPath: string = endpoints.apiEndpoint
) => {
  const mApp: any = app;

  const httpRoutes = routes.filter((r: RouteInfo) => r.requestType === 'HTTP');

  for (const route of httpRoutes) {
    if (route.path && route.method) {
      const method = route.method.toLowerCase();
      const routePath = `${rootPath}${route.path.startsWith('/') ? route.path : `/${route.path}`}`;

      logger.info(`Registering HTTP route: [${method.toUpperCase()}] ${routePath}`);

      mApp[method](
        routePath,
        async (req: any, res: any, next: any) => {
          const mReq: Request = req;
          const mRes: Response = res;
          const ctx: ServiceContext = {
            req: mReq,
            res: mRes,
          };

          try {
            const moduleName = route.serviceClass?.replace('Service', '').toLowerCase();
            const serviceUrl = new URL(`../services/${moduleName}.js`, import.meta.url);
            const serviceModule = await import(serviceUrl.href);
            const ServiceClass = serviceModule[String(route.serviceClass)] || serviceModule.ServiceClass;
            const serviceInstance = new ServiceClass(ctx, mReq.body ?? {});
            const handler = serviceInstance[String(route.serviceMethod)];

            const rawResult = await invoker.invokeWithParsedArgs(handler.bind(serviceInstance), mReq.body, handler);

            const result: Record<string, unknown> = isRecord(rawResult) ? rawResult : {};

            const response = {
              code: typeof result['code'] === 'number' ? result['code'] : DEFAULT_SUCCESS_STATUS_CODE,
              data: Array.isArray(result['data']) || isRecord(result['data']) ? result['data'] : undefined,
              message: typeof result['message'] === 'string' ? result['message'] : 'Request processed successfully',
              sessionId: typeof result['sessionId'] === 'string' ? result['sessionId'] : undefined,
              success: typeof result['success'] === 'boolean' ? result['success'] : true,
            };

            const statusCode = typeof response.code === 'number' ? response.code : DEFAULT_SUCCESS_STATUS_CODE;
            mRes.status(statusCode).json(response);
          } catch (error: any) {
            logger.error(`Error handling HTTP route [${method.toUpperCase()}] ${routePath}:`, error);
            next(error);
          }
        }
      );
    }
  }
};

