export const loggingOptions: MiddlewareLoggingOptionsType = {
  logBody: false,
  logHeaders: false,
  logParams: false,
  logQuery: false,
};

export const syncLocals = (opts: any): void => {
  const {
    locals,
    req,
    res,
    target = 'both',
  } = opts;

  if (typeof target !== 'string' || !['both', 'req', 'res'].includes(target)) {
    throw new Error('Target must be either "both", "req", or "res"');
  }

  if (!locals) {
    throw new Error('Locals must be provided to sync local variables');
  }

  if (!(req || res)) {
    throw new Error(
      'Either req or res must be provided to sync local variables'
    );
  }

  const allLocals = utils.serialize.safeClone({
    ...(req?.locals ? req.locals : {}),
    ...(res?.locals ? res.locals : {}),
    ...locals,
  });

  if (req && (target === 'req' || target === 'both')) {
    const reqLocals: any = utils.serialize.safeClone(allLocals || {});
    if (reqLocals['originalStatusCode']) {
      // biome-ignore lint/performance/noDelete: ignore
      delete reqLocals['originalStatusCode'];
    }
    if (reqLocals['responseBody']) {
      // biome-ignore lint/performance/noDelete: ignore
      delete reqLocals['responseBody'];
    }
    req.locals = {
      ...req.locals,
      ...reqLocals,
    };
  }

  if (res && (target === 'res' || target === 'both')) {
    const resLocals: any = utils.serialize.safeClone(allLocals || {});
    res.locals = utils.serialize.safeClone({
      ...res.locals,
      ...resLocals,
    });
  }
};

export const gatewayMiddleware = (
  req: any,
  res: any,
  next: any
): void => {
  const mReq: Request = req;
  const mRes: Response = res;
  const _mNext: NextFunction = next;

  // Wrap response first to capture body, then handle request start
  responseHandler(mReq, mRes, () => {
    requestHandler(mReq, mRes, _mNext);
  });
};

import process from 'node:process';
import { endpoints } from '@lightproject/common/configs';
import {
  isCi,
  isLocal,
  isNonProduction,
  isOtherEnvironment,
  isTest,
} from '@lightproject/common/environment';
import { logger } from '@lightproject/common/logger';

import type {
  NextFunction,
  Request,
  Response,
} from '../types/middlware';

import { errorHandler } from './error-handler';

const logDebugTruthTable = (
  isLoopback: boolean,
  inSafeEnv: boolean,
  allowAll: boolean,
  blockAll: boolean,
  isAllowed: boolean
) => {
  if (!isNonProduction() || process.env['DEBUG'] !== 'true') {
    return;
  }

  const bools = [false, true];
  logger.debug('--- trustProxy decision truth table ---');
  for (const loopback of bools) {
    for (const safe of bools) {
      for (const allow of bools) {
        for (const block of bools) {
          const allowedByBlock = !block;
          const allowedByAllow = allow;
          const allowedByEnv = loopback || safe;
          const decision = allowedByBlock && (allowedByAllow || allowedByEnv);
          logger.debug(
            `isLoopback=${loopback}, inSafeEnv=${safe}, allowAll=${allow}, blockAll=${block} => isAllowed=${decision}`
          );
        }
      }
    }
  }
  logger.debug('--- actual flags ---');
  logger.debug(
    `isLoopback=${isLoopback}, inSafeEnv=${inSafeEnv}, allowAll=${allowAll}, blockAll=${blockAll} => isAllowed=${isAllowed}`
  );
};

const handleAccessDenied = (
  req: any,
  res: any,
  next: any
) => {
  const mReq: Request = req;
  const mRes: Response = res;
  const _mNext: NextFunction = next;

  const statusCode = 403;
  const error = {
    message: 'Access denied',
    name: 'AccessDeniedError',
    stack: 'No stack trace available',
    statusCode,
  };

  mRes.status(statusCode);

  if (endpoints.isTrpcEndpoint(mReq.originalUrl)) {
    errorHandler(
      error,
      mReq,
      mRes,
      _mNext
    );
  } else {
    _mNext(error);
  }
};

export const trustProxyMiddleware = (
  req: any,
  res: any,
  next: any
) => {
  const mReq: Request = req;
  const mRes: Response = res;
  const _mNext: NextFunction = next;

  const allowedIps = new Set(['127.0.0.1', '::1']);
  const requestIp = mReq.ip || mReq.socket.remoteAddress;

  const isLoopback = !!requestIp && allowedIps.has(requestIp);
  const inSafeEnv = isLocal() || isTest() || isCi() || isOtherEnvironment();
  const allowAll = process.env['ALLOW_ALL_IPS'] === 'true';
  const blockAll = process.env['BLOCK_ALL_IPS'] === 'true';

  // Precedence: blockAll > allowAll > (isLoopback || inSafeEnv)
  const isAllowed = !blockAll && (allowAll || isLoopback || inSafeEnv);

  logDebugTruthTable(isLoopback, inSafeEnv, allowAll, blockAll, isAllowed);

  if (isAllowed) {
    _mNext();
  } else {
    handleAccessDenied(mReq, mRes, _mNext);
  }
};

