import type { InputArgs, ServiceContext } from '../types/middlware';

interface BaseServiceInterface {
  /**
   * Method to clean up resources used by the service.
   * This method is intended to be overridden by derived classes to perform cleanup operations.
   */
  cleanup?(): Promise<void>;

  /**
   * The context of the service, which contains the request and response objects.
   * This property is used to access the request and response objects in the service methods.
   */
  context: Readonly<ServiceContext>;

  /**
   * Getter for the context of the service.
   * This method is used to get the context of the service.
   * It is intended to be used by derived classes to access the context of the service.
   */
  get ctx(): Readonly<ServiceContext>;

  /**
   * Setter for the context of the service.
   * This method is used to set the context of the service.
   * It is intended to be used by derived classes to set the context of the service.
   */
  set ctx(ctx: Readonly<ServiceContext>);

  /**
   * Static method to get the singleton instance of the service.
   * This method is used to get the singleton instance of the service.
   * It is intended to be used by derived classes to get the singleton instance of the service.
   */
  getInstance(): BaseServiceInterface;

  /**
   * Getter for the input arguments of the service.
   * This method is used to get the input arguments for the service methods.
   * It is intended to be used by derived classes to access the input arguments for the service methods.
   */
  get input(): Readonly<InputArgs>;

  /**
   * Setter for the input arguments of the service.
   * This method is used to set the input arguments for the service methods.
   * It is intended to be used by derived classes to set the input arguments for the service methods.
   */
  set input(inputArgs: Readonly<InputArgs>);

  /**
   * Input arguments for the service.
   * This property is used to store the input arguments passed to the service methods.
   */
  inputArgs: Readonly<InputArgs>;

  /**
   * Instance of the service.
   * This is a static property that holds the singleton instance of the service.
   * It is used to ensure that only one instance of the service is created.
   */
  instance: BaseServiceInterface | null;
}

interface BaseServiceConstructor {
  new (ctx: Readonly<ServiceContext>, inputArgs?: Readonly<InputArgs>): BaseService;
  getInstance(): BaseServiceInterface;
  instance: BaseService | null;
}

function isBaseServiceConstructor(ctor: unknown): ctor is BaseServiceConstructor {
  return typeof ctor === 'function' && 'getInstance' in ctor && 'instance' in ctor;
}

abstract class BaseService implements BaseServiceInterface {
  static instance: BaseService | null = null;

  context: Readonly<ServiceContext>;
  inputArgs: Readonly<InputArgs> = {};

  get ctx(): Readonly<ServiceContext> {
    return this.context;
  }

  set ctx(ctx: Readonly<ServiceContext>) {
    this.context = ctx;
  }

  get input(): Readonly<InputArgs> {
    return this.inputArgs;
  }

  set input(inputArgs: Readonly<InputArgs>) {
    this.inputArgs = inputArgs;
  }

  get instance(): BaseServiceInterface | null {
    const ctor = this.constructor;
    return isBaseServiceConstructor(ctor) ? ctor.instance : null;
  }

  set instance(value: BaseServiceInterface | null) {
    const ctor = this.constructor;
    if (isBaseServiceConstructor(ctor)) {
      if (value instanceof BaseService || value === null) {
        ctor.instance = value;
      }
    }
  }

  constructor(ctx: Readonly<ServiceContext>, inputArgs: Readonly<InputArgs> = {}) {
    this.context = ctx;
    this.inputArgs = inputArgs;
  }

  static getInstance<T extends BaseService>(
    this: new (
      ctx: Readonly<ServiceContext>,
      inputArgs?: Readonly<InputArgs>
    ) => T
  ): T {
    if (!BaseService.instance) {
      // Create a dummy context for singleton pattern
      const dummyContext: ServiceContext = {
        req: JSON.parse('{}'),
        res: JSON.parse('{}'),
      };
      // biome-ignore lint/complexity/noThisInStatic: ignore
      BaseService.instance = new this(dummyContext);
    }
    const instance = BaseService.instance;
    if (instance instanceof this) {
      return instance;
    }
    throw new Error('Failed to create instance or instance type mismatch');
  }

  getInstance(): BaseServiceInterface {
    const ctor = this.constructor;
    if (isBaseServiceConstructor(ctor)) {
      return ctor.getInstance();
    }
    throw new Error('Failed to get service instance');
  }

  cleanup?(): Promise<void> {
    return Promise.resolve();
  }
}

export { BaseService };
export type { BaseServiceInterface };

import { utils } from '@lightproject/common';

import type {
  MiddlewareLoggingOptionsType,
  NextFunction,
  Request,
  Response,
} from '../types/middlware';

import { requestHandler } from './request-handler';
import { responseHandler } from './response-handler';

export const loggingOptions: MiddlewareLoggingOptionsType = {
  logBody: false,
  logHeaders: false,
  logParams: false,
  logQuery: false,
};

export const syncLocals = (opts: any): void => {
  const {
    locals,
    req,
    res,
    target = 'both',
  } = opts;

  if (typeof target !== 'string' || !['both', 'req', 'res'].includes(target)) {
    throw new Error('Target must be either "both", "req", or "res"');
  }

  if (!locals) {
    throw new Error('Locals must be provided to sync local variables');
  }

  if (!(req || res)) {
    throw new Error(
      'Either req or res must be provided to sync local variables'
    );
  }

  const allLocals = utils.serialize.safeClone({
    ...(req?.locals ? req.locals : {}),
    ...(res?.locals ? res.locals : {}),
    ...locals,
  });

  if (req && (target === 'req' || target === 'both')) {
    const reqLocals: any = utils.serialize.safeClone(allLocals || {});
    if (reqLocals['originalStatusCode']) {
      // biome-ignore lint/performance/noDelete: ignore
      delete reqLocals['originalStatusCode'];
    }
    if (reqLocals['responseBody']) {
      // biome-ignore lint/performance/noDelete: ignore
      delete reqLocals['responseBody'];
    }
    req.locals = {
      ...req.locals,
      ...reqLocals,
    };
  }

  if (res && (target === 'res' || target === 'both')) {
    const resLocals: any = utils.serialize.safeClone(allLocals || {});
    res.locals = utils.serialize.safeClone({
      ...res.locals,
      ...resLocals,
    });
  }
};

export const gatewayMiddleware = (
  req: any,
  res: any,
  next: any
): void => {
  const mReq: Request = req;
  const mRes: Response = res;
  const _mNext: NextFunction = next;

  // Wrap response first to capture body, then handle request start
  responseHandler(mReq, mRes, () => {
    requestHandler(mReq, mRes, _mNext);
  });
};

import type {
  HttpMethod,
  RouteHandler,
  ServiceContext,
} from '../types/middlware';

const HTTP_STATUS_OK = 200;
const HTTP_STATUS_INTERNAL_SERVER_ERROR = 500;

export const publicHttp = {
  delete: (handlerFactory: () => unknown) => ({
    handler: handlerFactory(),
    method: 'delete',
  }),
  get: (handlerFactory: () => unknown) => ({
    handler: handlerFactory(),
    method: 'get',
  }),
  options: (handlerFactory: () => unknown) => ({
    handler: handlerFactory(),
    method: 'options',
  }),
  patch: (handlerFactory: () => unknown) => ({
    handler: handlerFactory(),
    method: 'patch',
  }),
  post: (handlerFactory: () => unknown) => ({
    handler: handlerFactory(),
    method: 'post',
  }),
  put: (handlerFactory: () => unknown) => ({
    handler: handlerFactory(),
    method: 'put',
  }),
};

export const makeHttp = (method: HttpMethod) => {
  return (handlerFactory: () => RouteHandler) => ({
    handler: async (ctx: Readonly<ServiceContext>) => {
      try {
        const input = ctx.req.body || ctx.req.query || ctx.req.params || {};
        const handler = handlerFactory();
        const mRes: any = ctx.res;
        const result = await Promise.resolve(handler({ ctx, input }));
        mRes.status(result.code || HTTP_STATUS_OK).json(result);
      } catch (error) {
        const mRes: any = ctx.res;
        mRes.status(HTTP_STATUS_INTERNAL_SERVER_ERROR).json({
          code: HTTP_STATUS_INTERNAL_SERVER_ERROR,
          error: String(error),
          message: 'Internal server error',
          success: false,
        });
      }
    },
    method,
  });
};

