  syncLocals({
    locals: {
      ...metadata,
    },
    req: mReq,
    res: mRes,
    target: 'both',
  });

  const serializedLocals = utils.serialize.safeSerialize({
    ...locals,
    ...mRes.locals,
  });

  logger.error(`Error [${mReq.method}]: ${errorMessage}`, serializedLocals);

  if (!enableErrorStack) {
    // biome-ignore lint/performance/noDelete: ignore
    delete error.stack;
  }

  if (throwError) {
    throw mErr;
  }

  return error;
};

export const getErrorResponse = (
  error: any,
  req: any,
  res: any
): BaseResponse => {
  const mError: any = error;
  const mReq: any = req;
  const mRes: any = res;

  const serializedError = isErrorDetails(mError) ? mError : getErrorDetails(mError, mRes);

  const errorResponse: BaseResponse = {
    code: mRes.statusCode,
    error: serializedError,
    message: serializedError.message || 'Error',
    sessionId: mReq.locals?.sessionId || undefined,
    success: false,
  };

  return errorResponse;
};

export const isErrorDetails = (value: unknown): value is ErrorDetails =>
  typeof value === 'object' &&
  value !== null &&
  'message' in value &&
  'name' in value &&
  'statusCode' in value;

export const getStatusCode = (statusCode: any): number => {
  const code = typeof statusCode === 'number' ? statusCode : 0;
  if (!code) {
    return HTTP_STATUS_INTERNAL_SERVER_ERROR;
  }

  return code === HTTP_STATUS_OK
    ? HTTP_STATUS_INTERNAL_SERVER_ERROR
    : code;
};

export const errorHandler = (
  err: any,
  req: any,
  res: any,
  next: any
): any => {
  const mReq: Request = req;
  const mRes: Response = res;
  const mErr: any = err;

  const errorDetails = handleError({
    err:
      mErr instanceof Error || isErrorDetails(mErr)
        ? mErr
        : new Error(typeof mErr === 'string' ? mErr : JSON.stringify(mErr)),
    req: mReq,
    res: mRes,
  });

  const errorResponse = getErrorResponse(errorDetails, mReq, mRes);
  const code = typeof errorResponse.code === 'number' ? errorResponse.code : HTTP_STATUS_INTERNAL_SERVER_ERROR;
  if (!mRes.headersSent) {
    mRes.status(code).json(errorResponse);
  } else {
    const locals = mReq.locals;
    logger.warn('Headers already sent, skipping errorHandler response', { sessionId: locals?.sessionId });
  }

  if (next) {
    // next is provided by express
  }
};

import { AsyncLocalStorage } from 'node:async_hooks';
import { randomUUID } from 'node:crypto';
import { endpoints } from '@lightproject/common/configs';
import { color } from '@lightproject/common/utils';
import type { ChalkInstance } from 'chalk';
import cryptoJs from 'crypto-js';

const uuidv4 = () => randomUUID();

import { logger } from '@lightproject/common/logger';

import type {
  Locals,
  NextFunction,
  Request,
  Response,
} from '../types/middlware';

import { syncLocals } from './gateway-middleware';

const asyncLocalStorage = new AsyncLocalStorage();

let previousColor: ChalkInstance | undefined;

export const initializeRequest = (
  req: any,
  res: any,
  next: any
) => {
  const mReq: Request = req;
  const mRes: Response = res;
  const _mNext: NextFunction = next;
  try {
    let locals = mReq.locals;
    if (!locals) {
      locals = {
        color: color.defaultColor,
        sessionId: 'initializing',
        metadata: {
          method: mReq.method,
          requestType: endpoints.getRequestType(mReq.originalUrl || '/'),
          source: 'initializeRequest',
          startTime: Date.now(),
          url: mReq.originalUrl || '/',
        },
      };
      mReq.locals = locals;
    }

    const sessionId = uuidv4();

    const { nextColor, previousColor: newPrevColor } = color.getNextRandomColor(
      cryptoJs.SHA256(sessionId).toString(),
      previousColor ?? color.defaultColor
    );
    locals.color = nextColor;
    previousColor = newPrevColor;

    previousColor = locals.color;

    const updatedLocals: Locals = {
      ...locals,
      metadata: {
        method: mReq.method,
        requestType: endpoints.getRequestType(mReq.originalUrl),
        source: 'initializeRequest',
        startTime: Date.now(),
        url: mReq.originalUrl,
      },
      sessionId,
    };

    syncLocals({
      locals,
      req: mReq,
      target: 'req',
    });

    logger.info(`Initializing [${mReq.method}] request session`, mReq.locals);

    asyncLocalStorage.run(new Map<string, any>([['locals', updatedLocals]]), () => {
      mRes.locals = updatedLocals;
      const resLocals: any = mRes.locals;
      resLocals.originalStatusCode = mRes.statusCode;
      _mNext();
    });
  } catch (error) {
    next(error);
  }
};

const isLocals = (val: unknown): val is Locals =>
  typeof val === 'object' && val !== null && 'sessionId' in val && 'color' in val;

export const getSessionId = () => {
  const store = asyncLocalStorage.getStore();
  if (store instanceof Map) {
    const locals = store.get('locals');
    if (isLocals(locals)) {
      return String(locals.sessionId);
    }
  }
  return 'no-id';
};

export const getColor = () => {
  const store = asyncLocalStorage.getStore();
  if (store instanceof Map) {
    const locals = store.get('locals');
    if (isLocals(locals) && locals.color) {
      return locals.color;
    }
  }
  return color.getRandomColor();
};

export const getLocals = () => {
  const store = asyncLocalStorage.getStore();
  if (store instanceof Map) {
    const locals = store.get('locals');
    if (isLocals(locals)) {
      return locals;
    }
  }
  return { color: color.getRandomColor(), sessionId: 'no-id' };
};

