import { logger } from '@lightproject/common/logger';
import { invoker } from '@lightproject/common/utils';

import type { BaseService } from '../services/base';

const DEFAULT_SUCCESS_CODE = 200;

import type {
  BaseResponse,
  InputArgs,
  RouteHandler,
  ServiceContext,
  ServiceMethod,
} from '../types/middlware';

const isRecord = (val: unknown): val is Record<string, unknown> =>
  typeof val === 'object' && val !== null && !Array.isArray(val);

const isServiceMethod = (val: unknown): val is ServiceMethod =>
  typeof val === 'function';

// Define a callable interface with overloads (HTTP + tRPC)
// Implementation with overloads below

// Single arrow implementation that satisfies the broader (tRPC) param shape
function createRouteHandler<S extends BaseService>(
  serviceClass: new (ctx: Readonly<ServiceContext>, inputArgs?: Readonly<InputArgs>) => S,
  method: keyof S
): (opts: Readonly<{ ctx: Readonly<ServiceContext>; input: unknown }>) => Promise<BaseResponse>;
function createRouteHandler<S extends BaseService>(
  serviceClass: new (ctx: Readonly<ServiceContext>, inputArgs?: Readonly<InputArgs>) => S,
  method: keyof S
): RouteHandler;
function createRouteHandler<S extends BaseService>(
  serviceClass: new (ctx: Readonly<ServiceContext>, inputArgs?: Readonly<InputArgs>) => S,
  method: keyof S
): any {
  return async ({ ctx, input }: Readonly<{ ctx: Readonly<ServiceContext>; input: unknown }>) => {
    try {
      const inputArgs: InputArgs = {};
      if (typeof input === 'object' && input !== null) {
        Object.assign(inputArgs, input);
      }
      const serviceInstance = new serviceClass(ctx, inputArgs);
      const serviceMethod = serviceInstance[method];

      if (!isServiceMethod(serviceMethod)) {
        throw new Error(
          `Method ${String(method)} is not a valid service method on ${
            serviceClass.name
          }`
        );
      }

      // Use a safe wrapper for invoker call
      const rawResult = await Promise.resolve(
        invoker.invokeWithParsedArgs(
          serviceMethod,
          serviceInstance.input
        )
      );

      const result: Record<string, unknown> = isRecord(rawResult) ? rawResult : {};

      const response: BaseResponse = {
        code:
          typeof result['code'] === 'number'
            ? result['code']
            : DEFAULT_SUCCESS_CODE,
        data:
          Array.isArray(result['data']) || isRecord(result['data'])
            ? (result['data'] as BaseResponse['data'])
            : undefined,
        message:
          typeof result['message'] === 'string'
            ? result['message']
            : 'Request processed successfully',
        sessionId:
          typeof result['sessionId'] === 'string'
            ? result['sessionId']
            : undefined,
        success:
          typeof result['success'] === 'boolean' ? result['success'] : true,
      };

      return response;
    } catch (error) {
      logger.error(
        `Error in route handler for ${serviceClass.name}.${String(method)}:`,
        error
      );
      throw error;
    }
  };
}

