import 'express';
import type { endpoints } from '@lightproject/common/configs';
import type { ChalkInstance } from 'chalk';
import type {
  NextFunction as ExpressNextFunction,
  Request as ExpressRequest,
  Response as ExpressResponse,
} from 'express';
import type { Primitive } from 'zod';

export interface BaseResponse {
  readonly [key: string]: unknown;
  readonly code?: null | number | undefined;
  readonly data?:
    | null
    | Readonly<Record<string, unknown>>
    | readonly Readonly<Record<string, unknown>>[]
    | undefined;
  readonly error?: Error | null | undefined;
  readonly message?: string;
  readonly sessionId?: SessionId;
  success: boolean;
}

export type Body = null | Record<string, unknown> | string | undefined;

export interface ErrorDetails {
  readonly statusCode: number;
  message: string;
  name: string;
  stack?: string;
}

export type ExpressHandler = (
  req: ReadonlyRequest,
  res: ReadonlyResponse,
  next: any
) => void;

export type ExpressErrorHandler = (
  err: any,
  req: ReadonlyRequest,
  res: ReadonlyResponse,
  next: any
) => void;

export type Headers = null | Record<string, unknown> | string | undefined;

export type HttpMethod =
  | 'delete'
  | 'get'
  | 'head'
  | 'options'
  | 'patch'
  | 'post'
  | 'put';

export interface InputArgs {
  readonly [key: string]: Primitive | Readonly<Record<string, unknown>> | readonly unknown[];
}

export interface MiddlewareLocals {
  color?: ChalkInstance | undefined;
  error?: ErrorDetails;
  metadata: Metadata;
  sessionId: SessionId;
  readonly [key: string]: unknown;
}

export interface Metadata {
  readonly [key: string]: unknown;
  readonly body?: Body;
  readonly headers?: Headers;
  readonly method: string;
  readonly params?: Params;
  readonly query?: Query;
  requestType: endpoints.RequestType;
  startTime: number;
  url: string;
  duration?: number | undefined;
  endTime?: number | undefined;
  error?: Error | ErrorDetails | null | undefined;
}

export interface MiddlewareLoggingOptionsType {
  readonly logBody?: boolean;
  readonly logHeaders?: boolean;
  readonly logParams?: boolean;
  readonly logQuery?: boolean;
}

export type NextFunction = ExpressNextFunction;

export type OriginalStatusCode = null | number | undefined;

export type Params = null | Record<string, unknown> | string | undefined;

export type Query = null | Record<string, unknown> | string | undefined;

export type ResponseBody = null | Record<string, unknown> | string | undefined;

export type RouteHandler = (params: Readonly<{
  ctx: Readonly<ServiceContext>;
  input?: Readonly<InputArgs>;
}>) => BaseResponse | Promise<BaseResponse>;

export interface ServiceContext {
  readonly next?: NextFunction | null | undefined;
  readonly req: ReadonlyRequest;
  readonly res: ReadonlyResponse;
}

declare global {
  namespace Express {
   export interface RequestLocalsSyncOptions {
  locals: Readonly<MiddlewareLocals>;
  req: ReadonlyRequest;
  res: ReadonlyResponse;
  target: 'both' | 'req' | 'res';
}
    interface Request {
      locals?: MiddlewareLocals;
    }
    interface Response {
      locals: MiddlewareLocals & {
        originalStatusCode?: OriginalStatusCode;
        responseBody?: ResponseBody;
      };
    }
  }
}

export type Request = ExpressRequest;
export type Response = ExpressResponse;

export type ServiceMethod = (
  ...args: readonly unknown[]
) => BaseResponse | Promise<BaseResponse>;

export type SessionId = null | string | undefined;

export const HTTP_STATUS_OK = 200;
export const HTTP_STATUS_CREATED = 201;
export const HTTP_STATUS_NO_CONTENT = 244;
export const HTTP_STATUS_BAD_REQUEST = 400;
export const HTTP_STATUS_UNAUTHORIZED = 401;
export const HTTP_STATUS_FORBIDDEN = 403;
export const HTTP_STATUS_NOT_FOUND = 404;
export const HTTP_STATUS_INTERNAL_SERVER_ERROR = 500;

export type {
  NextFunction as ExpressNextFunction,
  Request as ExpressRequest,
  Response as ExpressResponse,
} from 'express';

export type Locals = MiddlewareLocals;



export interface ReadonlyError {
  readonly message: string;
  readonly name: string;
  readonly stack?: string;
}

export interface ReadonlyRequest {
  readonly method: string;
  readonly originalUrl: string;
  readonly locals?: any;
  readonly body: any;
  readonly params: any;
  readonly query: any;
}

export interface ReadonlyResponse {
  readonly locals: any;
  readonly statusCode: number;
  readonly getHeaders: () => any;
}

