/**
 * OpenAPI operation definition
 */
interface OpenApiOperation {
  readonly description?: string;
  readonly parameters?: readonly OpenApiParameter[];
  readonly requestBody?: {
    readonly content: Readonly<Record<string, { readonly schema: OpenApiSchema }>>;
    readonly required?: boolean;
  };
  readonly responses: Readonly<Record<string, OpenApiResponse>>;
  readonly summary?: string;
  readonly tags?: readonly string[];
}

/**
 * OpenAPI parameter definition
 */
interface OpenApiParameter {
  readonly description?: string;
  readonly in: 'cookie' | 'header' | 'path' | 'query';
  readonly name: string;
  readonly required?: boolean;
  readonly schema: OpenApiSchema;
}

/**
 * OpenAPI response definition
 */
interface OpenApiResponse {
  readonly content?: Readonly<Record<string, { readonly schema: OpenApiSchema }>>;
  readonly description: string;
}

/**
 * OpenAPI schema definition
 */
interface OpenApiSchema {
  readonly allOf?: readonly OpenApiSchema[];
  readonly anyOf?: readonly OpenApiSchema[];
  readonly default?: unknown;
  readonly description?: string;
  readonly example?: unknown;
  readonly format?: string;
  readonly items?: OpenApiSchema;
  readonly oneOf?: readonly OpenApiSchema[];
  readonly properties?: Readonly<Record<string, OpenApiSchema>>;
  readonly required?: readonly string[];
  readonly type?: string;
}

/**
 * Constants for example values
 */
const EXAMPLE_NUMBER_VALUE = 123;
const EXAMPLE_SECOND_NUMBER_VALUE = 456;
const HTTP_STATUS_BAD_REQUEST = 400;
const HTTP_STATUS_INTERNAL_SERVER_ERROR = 500;

/**
 * Example values for OpenAPI schema generation
 */
const EXAMPLE_VALUES = {
  booleanArray: [true, false],
  booleanValue: true,
  httpStatusBadRequest: HTTP_STATUS_BAD_REQUEST,
  httpStatusInternalError: HTTP_STATUS_INTERNAL_SERVER_ERROR,
  numberArray: [EXAMPLE_NUMBER_VALUE, EXAMPLE_SECOND_NUMBER_VALUE],
  numberValue: EXAMPLE_NUMBER_VALUE,
  stringArray: ['ABC', 'DEF'],
  stringValue: 'ABC',
} as const;

/**
 * OpenAPI 3.0 specification structure
 */
interface OpenApiSpec {
  components?: {
    schemas?: Record<string, OpenApiSchema>;
  };
  info: {
    description?: string;
    title: string;
    version: string;
  };
  openapi: string;
  paths: Record<string, Record<string, OpenApiOperation>>;
  servers: Array<{
    description?: string;
    url: string;
  }>;
}

/**
 * Generate OpenAPI 3.0 specification from route information
 */
const generateOpenApiSpec = (
  routes: readonly RouteInfo[],
  options: Readonly<{
    description?: string;
    serverUrl?: string;
    title?: string;
    version?: string;
  }> = {}
): OpenApiSpec => {
  const {
    description = 'Auto-generated API documentation from route discovery',
    serverUrl = 'http://localhost:3000',
    title = 'Pancake API',
    version = '1.0.0',
  } = options;

  const spec: OpenApiSpec = {
    components: {
      schemas: {},
    },
    info: {
      description,
      title,
      version,
    },
    openapi: '3.0.3',
    paths: {},
    servers: [
      {
        description: 'Development server',
        url: serverUrl,
      },
    ],
  };

  // Group routes by path and method
  const pathGroups = groupRoutesByPath(routes);

  // Generate paths
  for (const [path, pathRoutes] of Object.entries(pathGroups)) {
    const pathOps: Record<string, OpenApiOperation> = {};

    for (const route of pathRoutes) {
      const method = (route.method || 'get').toLowerCase();
      pathOps[method] = generateOperation(route);
    }
    spec.paths[path] = pathOps;
  }

  return spec;
};

/**
 * Group routes by normalized path
 */
const groupRoutesByPath = (
  routes: readonly RouteInfo[]
): Record<string, readonly RouteInfo[]> => {
  const groups: Record<string, RouteInfo[]> = {};

  for (const route of routes) {
    // Normalize path - handle empty paths
    let normalizedPath = route.path || '/';

    // Ensure path starts with /
    if (!normalizedPath.startsWith('/')) {
      normalizedPath = `/${normalizedPath}`;
    }

    if (!groups[normalizedPath]) {
      groups[normalizedPath] = [];
    }

    groups[normalizedPath]?.push(route);
  }

  return groups;
};

/**
 * Generate OpenAPI operation from route info
 */
const generateOperation = (route: Readonly<RouteInfo>): OpenApiOperation => {
  const method = (route.method || 'get').toLowerCase();

  const parameters =
    route.input &&
    route.input.length > 0 &&
    ['delete', 'get', 'head'].includes(method)
      ? route.input.map(param => convertToQueryParameter(param))
      : undefined;

  const requestBody =
    route.input &&
    route.input.length > 0 &&
    !['delete', 'get', 'head'].includes(method)
      ? {
          content: {
            'application/json': {
              schema: convertParametersToRequestBodySchema(route.input),
            },
          },
          required: route.input.some(p => p.required),
        }
      : undefined;

  return {
    description: generateOperationDescription(route),
    ...(parameters ? { parameters } : {}),
    ...(requestBody ? { requestBody } : {}),
    responses: generateResponses(route),
    summary: generateOperationSummary(route),
    tags: generateOperationTags(route),
  };
};

/**
 * Generate operation summary
 */
const generateOperationSummary = (route: Readonly<RouteInfo>): string => {
  const serviceName = route.serviceClass?.replace('Service', '') || 'Unknown';
  const methodName = route.serviceMethod || 'unknown';

  if (route.requestType === 'tRPC') {
    const procedureType = route.type === 'mutation' ? 'Mutation' : 'Query';
    return `${serviceName} ${methodName} (${procedureType})`;
  }

  return `${serviceName} ${methodName}`;
};

/**
 * Generate operation description with enhanced context
 */
const generateOperationDescription = (route: Readonly<RouteInfo>): string => {
  // Try to generate a more descriptive description based on method patterns
  const enhancedDescription = generateMethodDescription(
    route.serviceMethod,
    route.serviceClass
  );

  if (enhancedDescription) {
    return enhancedDescription;
  }

  // Fallback to basic description
  const parts: string[] = [];

  if (route.serviceClass && route.serviceMethod) {
    parts.push(`Calls ${route.serviceClass}.${route.serviceMethod}()`);
  }

  if (route.requestType === 'tRPC') {
    parts.push(`tRPC ${route.type || 'query'} procedure`);
  } else {
    parts.push('HTTP endpoint');
  }

  return parts.join(' - ');
};

/**
 * Generate enhanced method description based on method name and service class
 */
const generateMethodDescription = (
  methodName?: string,
  serviceClass?: string
): string | undefined => {
  if (!(methodName && serviceClass)) {
    return undefined;
  }

  const service = serviceClass.replace('Service', '');

  // Method prefix lengths for resource extraction
  const GetPrefixLength = 3; // "get".length
  const CreateAddPrefixLength = 6; // "create".length, "add".length
  const UpdateEditPrefixLength = 6; // "update".length, "edit".length
  const DeleteRemovePrefixLength = 6; // "delete".length, "remove".length

  // Handle common method patterns
  if (methodName === 'root') {
    return `Get ${service} service status and basic information`;
  }

  if (methodName.startsWith('get')) {
    const resource = methodName.slice(GetPrefixLength);
    return `Retrieve ${resource.toLowerCase()} data from ${service}`;
  }

  if (methodName.startsWith('create') || methodName.startsWith('add')) {
    const resource = methodName.slice(CreateAddPrefixLength);
    return `Create new ${resource.toLowerCase()} in ${service}`;
  }

  if (methodName.startsWith('update') || methodName.startsWith('edit')) {
    const resource = methodName.slice(UpdateEditPrefixLength);
    return `Update existing ${resource.toLowerCase()} in ${service}`;
  }

  if (methodName.startsWith('delete') || methodName.startsWith('remove')) {
    const resource = methodName.slice(DeleteRemovePrefixLength);
    return `Delete ${resource.toLowerCase()} from ${service}`;
  }

  if (methodName.includes('Success')) {
    return `Execute ${methodName.replace('Success', '')} operation successfully`;
  }

  if (methodName.includes('Fail')) {
    return `Simulate ${methodName.replace('Fail', '')} operation failure for testing`;
  }

  if (methodName.startsWith('hello')) {
    return 'Generate personalized greeting message';
  }

  if (methodName.includes('Params')) {
    return 'Test and validate various parameter types and structures';
  }

  if (methodName === 'mixedParams') {
    return 'Process mixed parameter types including primitives, objects, and arrays';
  }

  if (methodName === 'objectOnly') {
    return 'Process object-only parameters with optional properties';
  }

  if (methodName === 'objectDestructured') {
    return 'Process destructured object parameters';
  }

  if (methodName === 'primitivesAndArray') {
    return 'Process primitive parameters and array data';
  }

  return undefined; // Let the caller use fallback description
};

/**
 * Generate operation tags
 */
const generateOperationTags = (route: Readonly<RouteInfo>): readonly string[] => {
  const tags: string[] = [];

  // Add service-based tag
  if (route.serviceClass) {
    tags.push(route.serviceClass.replace('Service', ''));
  }

  // Add request type tag
  tags.push(route.requestType);

  return tags;
};

/**
 * Generate responses for the operation with enhanced schemas
 */
const generateResponses = (
  route: Readonly<RouteInfo>
): Record<string, OpenApiResponse> => {
  const successSchema = generateEnhancedResponseSchema(route.serviceMethod);

  return {
    '200': {
      content: {
        'application/json': {
          schema: successSchema,
        },
      },
      description: 'Successful response',
    },
    '400': {
      content: {
        'application/json': {
          schema: {
            properties: {
              error: {
                description: 'Error message',
                type: 'string',
              },
              statusCode: {
                description: 'HTTP status code',
                example: EXAMPLE_VALUES.httpStatusBadRequest,
                type: 'number',
              },
            },
            required: ['error', 'statusCode'],
            type: 'object',
          },
        },
      },
      description: 'Bad request - Invalid input parameters',
    },
    '500': {
      content: {
        'application/json': {
          schema: {
            properties: {
              error: {
                description: 'Internal error message',
                type: 'string',
              },
              statusCode: {
                description: 'HTTP status code',
                example: EXAMPLE_VALUES.httpStatusInternalError,
                type: 'number',
              },
            },
            required: ['error', 'statusCode'],
            type: 'object',
          },
        },
      },
      description: 'Internal server error',
    },
  };
};

/**
 * Generate enhanced response schema based on method patterns
 */
const generateEnhancedResponseSchema = (methodName?: string): OpenApiSchema => {
  if (!methodName) {
    return getDefaultResponseSchema();
  }

  // Pattern-based response schemas
  if (methodName === 'root') {
    return {
      properties: {
        message: {
          description: 'Service status message',
          example: 'OK',
          type: 'string',
        },
      },
      required: ['message'],
      type: 'object',
    };
  }

  if (methodName.includes('Success')) {
    return {
      properties: {
        message: {
          description: 'Success confirmation message',
          example: 'Operation completed successfully',
          type: 'string',
        },
      },
      required: ['message'],
      type: 'object',
    };
  }

  if (methodName.startsWith('hello')) {
    return {
      properties: {
        message: {
          description: 'Personalized greeting message',
          example: 'Hello, John Doe!',
          type: 'string',
        },
      },
      required: ['message'],
      type: 'object',
    };
  }

  if (
    methodName.includes('Params') ||
    methodName === 'mixedParams' ||
    methodName === 'objectOnly' ||
    methodName === 'objectDestructured' ||
    methodName === 'primitivesAndArray'
  ) {
    return {
      properties: {
        data: {
          description: 'Processed input parameters and their values',
          properties: {
            // This would be dynamically generated based on input parameters
          },
          type: 'object',
        },
        message: {
          description: 'Processing confirmation message',
          example: 'Parameters processed successfully',
          type: 'string',
        },
      },
      required: ['message'],
      type: 'object',
    };
  }

  if (methodName === '_checkParams') {
    return {
      properties: {
        booleanArrayOutput: {
          example: EXAMPLE_VALUES.booleanArray,
          items: { type: 'boolean' },
          type: 'array',
        },
        booleanOutput: {
          example: EXAMPLE_VALUES.booleanValue,
          type: 'boolean',
        },
        numberArrayOutput: {
          example: EXAMPLE_VALUES.numberArray,
          items: { type: 'number' },
          type: 'array',
        },
        numberOutput: {
          example: EXAMPLE_VALUES.numberValue,
          type: 'number',
        },
        objectBooleanArrayOutput: {
          properties: {
            booleanArray: {
              items: { type: 'boolean' },
              type: 'array',
            },
          },
          type: 'object',
        },
        objectBooleanOutput: {
          properties: {
            boolean: { type: 'boolean' },
          },
          type: 'object',
        },
        objectMultipleOutput: {
          description: 'Complex nested object with multiple data types',
          type: 'object',
        },
        objectNumberArrayOutput: {
          properties: {
            numberArray: {
              items: { type: 'number' },
              type: 'array',
            },
          },
          type: 'object',
        },
        objectNumberOutput: {
          properties: {
            number: { type: 'number' },
          },
          type: 'object',
        },
        objectStringArrayOutput: {
          properties: {
            stringArray: {
              items: { type: 'string' },
              type: 'array',
            },
          },
          type: 'object',
        },
        objectStringOutput: {
          properties: {
            string: { type: 'string' },
          },
          type: 'object',
        },
        stringArrayOutput: {
          example: EXAMPLE_VALUES.stringArray,
          items: { type: 'string' },
          type: 'array',
        },
        stringOutput: {
          example: EXAMPLE_VALUES.stringValue,
          type: 'string',
        },
      },
      type: 'object',
    };
  }

  // Default enhanced response
  return getDefaultResponseSchema();
};

/**
 * Get default response schema with enhanced structure
 */
const getDefaultResponseSchema = (): OpenApiSchema => {
  return {
    properties: {
      data: {
        description: 'Response data payload',
        type: 'object',
      },
      message: {
        description: 'Response message',
        type: 'string',
      },
      success: {
        description: 'Operation success indicator',
        type: 'boolean',
      },
    },
    type: 'object',
  };
};

/**
 * Convert parameter metadata to query parameter
 */
const convertToQueryParameter = (
  param: Readonly<ParameterMetadata>
): OpenApiParameter => {
  return {
    in: 'query',
    name: param.name,
    required: param.required,
    schema: convertTypeToSchema(param.type, param.defaultValue),
  };
};

/**
 * Convert parameters to request body schema
 */
const convertParametersToRequestBodySchema = (
  params: readonly ParameterMetadata[]
): OpenApiSchema => {
  const properties: Record<string, OpenApiSchema> = {};
  const requiredFields: string[] = [];

  for (const param of params) {
    properties[param.name] = convertTypeToSchema(
      param.type,
      param.defaultValue
    );

    if (param.required) {
      requiredFields.push(param.name);
    }
  }

  return {
    properties,
    ...(requiredFields.length > 0 ? { required: requiredFields } : {}),
    type: 'object',
  };
};

/**
 * Convert TypeScript type string to OpenAPI schema
 */
const convertTypeToSchema = (
  type: string,
  defaultValue?: unknown
): OpenApiSchema => {
  const schema: any = {};

  if (defaultValue !== undefined) {
    schema.default = defaultValue;
  }

  // Handle array types
  if (type.endsWith('[]')) {
    const itemType = type.slice(0, -2);
    return {
      default: defaultValue,
      items: convertTypeToSchema(itemType),
      type: 'array',
    };
  }

  // Handle union types (e.g., "string | undefined")
  if (type.includes(' | ')) {
    const unionTypes = type.split(' | ').map(t => t.trim());
    const nonUndefinedTypes = unionTypes.filter(t => t !== 'undefined');

    if (nonUndefinedTypes.length === 1) {
      const [singleType] = nonUndefinedTypes;
      if (singleType) {
        return convertTypeToSchema(singleType, defaultValue);
      }
    }

    return {
      default: defaultValue,
      oneOf: nonUndefinedTypes.map(t => convertTypeToSchema(t)),
    };
  }

  // Handle object types
  if (type.startsWith('{') && type.endsWith('}')) {
    return convertObjectTypeToSchema(type, defaultValue);
  }

  // Handle primitive types
  switch (type) {
    case 'any':
    case 'unknown': {
      return { default: defaultValue, description: 'Any value' };
    }
    case 'boolean': {
      return { default: defaultValue, type: 'boolean' };
    }
    case 'number': {
      return { default: defaultValue, type: 'number' };
    }
    case 'string': {
      return { default: defaultValue, type: 'string' };
    }
    default: {
      return {
        default: defaultValue,
        description: `Type: ${type}`,
        type: 'string',
      };
    }
  }
};

/**
 * Convert object type string to OpenAPI schema
 * Handles types like "{ foo: string; bar?: number; }"
 */
const convertObjectTypeToSchema = (
  type: string,
  defaultValue?: unknown
): OpenApiSchema => {
  const schema: OpenApiSchema = {
    default: defaultValue,
    properties: {},
    type: 'object',
  };

  // Simple parsing of object type - this could be enhanced with proper TypeScript AST parsing
  const content = type.slice(1, -1).trim(); // Remove { }

  if (!content) {
    return schema;
  }

  const required: string[] = [];
  const properties: Record<string, OpenApiSchema> = {};

  // Split by semicolon but handle nested objects
  const props = parseObjectProperties(content);

  for (const prop of props) {
    const colonIndex = prop.indexOf(':');
    if (colonIndex === -1) {
      continue;
    }

    const propName = prop.slice(0, colonIndex).trim();
    const propType = prop.slice(colonIndex + 1).trim();

    const isOptional = propName.endsWith('?');
    const cleanPropName = isOptional ? propName.slice(0, -1).trim() : propName;

    properties[cleanPropName] = convertTypeToSchema(propType);

    if (!isOptional) {
      required.push(cleanPropName);
    }
  }

  return {
    ...schema,
    properties,
    ...(required.length > 0 ? { required } : {}),
  } as OpenApiSchema;
};

/**
 * Parse object properties handling nested braces
 */
const parseObjectProperties = (content: string): string[] => {
  const properties: string[] = [];
  let current = '';
  let braceDepth = 0;

  for (const char of content) {
    if (char === '{') {
      braceDepth++;
    } else if (char === '}') {
      braceDepth--;
    } else if (char === ';' && braceDepth === 0) {
      if (current.trim()) {
        properties.push(current.trim());
      }
      current = '';
      continue;
    }

    current += char;
  }

  // Add the last property if it doesn't end with semicolon
  if (current.trim()) {
    properties.push(current.trim());
  }

  return properties;
};

// Export the main function at the end
export { generateOpenApiSpec };

import { logger } from '@lightproject/common/logger';

import type { RouteInfo } from '../types';

/**
 * Route validation configuration
 */
interface ValidationConfig {
  enforceServiceNaming: boolean;
  requiredServiceDirectory: string;
  strictConventions: boolean;
  validateParameters: boolean;
}

/**
 * Validation error types
 */
interface ValidationError {
  readonly code: string;
  readonly filePath?: string | undefined;
  readonly message: string;
  readonly path?: string | undefined;
  readonly severity: 'error' | 'warning';
  readonly suggestion?: string | undefined;
  readonly type: 'consistency' | 'convention' | 'naming' | 'structure';
}

/**
 * Validation result containing errors and warnings
 */
interface ValidationResult {
  readonly errors: readonly ValidationError[];
  readonly isValid: boolean;
  readonly warnings: readonly ValidationError[];
}

/**
 * Default validation configuration
 */
const DEFAULT_CONFIG: ValidationConfig = {
  enforceServiceNaming: true,
  requiredServiceDirectory: '/src/services/',
  strictConventions: true,
  validateParameters: true,
};

const SERVICE_NAME_REGEX = /Service$/;
const PASCAL_CASE_REGEX = /^[A-Z][a-zA-Z0-9]*Service$/;
const CAMEL_CASE_REGEX = /^[a-z][a-zA-Z0-9]*$/;
const PASCAL_CASE_METHOD_REGEX = /([A-Z])/g;
const LEADING_DASH_REGEX = /^-/;

/**
 * Comprehensive route validator for autogen system
 * Ensures routes follow expected conventions and patterns
 */
class RouteValidator {
  private readonly config: Readonly<ValidationConfig>;
  private errors: ValidationError[] = [];
  private warnings: ValidationError[] = [];

  constructor(config: Readonly<Partial<ValidationConfig>> = {}) {
    this.config = { ...DEFAULT_CONFIG, ...config };
  }

  /**
   * Format a single validation issue (error or warning)
   */
  private formatValidationIssue(issue: Readonly<ValidationError>): string {
    let output = `  - ${issue.code}: ${issue.message}\n`;

    if (issue.filePath) {
      output += `    File: ${issue.filePath}\n`;
    }

    if (issue.path) {
      output += `    Path: ${issue.path}\n`;
    }

    if (issue.suggestion) {
      output += `    💡 ${issue.suggestion}\n`;
    }

    return output;
  }

  /**
   * Format errors section of summary
   */
  private formatErrorsSection(errors: readonly ValidationError[]): string {
    if (errors.length === 0) {
      return '';
    }

    let section = `❌ Errors: ${errors.length}\n`;
    for (const error of errors) {
      section += this.formatValidationIssue(error);
    }
    return section;
  }

  /**
   * Format warnings section of summary
   */
  private formatWarningsSection(warnings: readonly ValidationError[]): string {
    if (warnings.length === 0) {
      return '';
    }

    let section = `⚠️  Warnings: ${warnings.length}\n`;
    for (const warning of warnings) {
      section += this.formatValidationIssue(warning);
    }
    return section;
  }

  /**
   * Get summary of validation results
   */
  getSummary(result: Readonly<ValidationResult>): string {
    const { errors, warnings } = result;
    const total = errors.length + warnings.length;

    if (total === 0) {
      return '✅ All routes passed validation';
    }

    let summary = `📋 Validation Summary: ${total} issues found\n`;
    summary += this.formatErrorsSection(errors);
    summary += this.formatWarningsSection(warnings);

    return summary;
  }

  /**
   * Validate all routes and return comprehensive results
   */
  validate(routes: readonly RouteInfo[]): ValidationResult {
    this.errors = [];
    this.warnings = [];

    logger.info(`Validating ${routes.length} routes...`);

    for (const route of routes) {
      this.validateRoute(route);
    }

    const isValid = this.errors.length === 0;

    if (isValid) {
      logger.info(
        `✅ All routes passed validation (${this.warnings.length} warnings)`
      );
    } else {
      logger.warn(
        `Validation found ${this.errors.length} errors and ${this.warnings.length} warnings`
      );
    }

    return {
      errors: this.errors,
      isValid,
      warnings: this.warnings,
    };
  }

  /**
   * Add error to validation results
   */
  private addError(error: Readonly<Omit<ValidationError, 'severity'>>): void {
    this.errors.push({ ...error, severity: 'error' });
  }

  /**
   * Add warning to validation results
   */
  private addWarning(warning: Readonly<Omit<ValidationError, 'severity'>>): void {
    this.warnings.push({ ...warning, severity: 'warning' });
  }

  /**
   * Get expected service filename from class name
   */
  private getExpectedServiceFileName(serviceClass: string): string {
    // Convert PascalCase to kebab-case: UserProfileService -> user-profile.ts
    const baseName = serviceClass.replace(SERVICE_NAME_REGEX, '');
    const kebabCase = baseName
      .replaceAll(
        PASCAL_CASE_METHOD_REGEX,
        (_, letter) => `-${letter.toLowerCase()}`
      )
      .replace(LEADING_DASH_REGEX, ''); // Remove leading dash

    return `${kebabCase}.ts`;
  }

  /**
   * Validate createRouteHandler pattern usage
   */
  private validateConventions(route: Readonly<RouteInfo>): void {
    if (!this.config.strictConventions) {
      return;
    }

    // Routes should have both service class and method
    if (!(route.serviceClass && route.serviceMethod)) {
      this.addError({
        code: 'MISSING_ROUTE_HANDLER_PATTERN',
        filePath: route.handlerFilePath,
        message:
          'Route must use createRouteHandler(ServiceClass, "methodName") pattern',
        path: route.path,
        suggestion: 'Use: createRouteHandler(MyService, "methodName")',
        type: 'convention',
      });
    }

    // Validate HTTP method consistency
    if (route.requestType === 'HTTP' && route.method) {
      this.validateHttpMethodConsistency(route);
    }

    // Validate tRPC procedure types
    if (route.requestType === 'tRPC' && route.type) {
      this.validateTrpcProcedureType(route);
    }
  }

  /**
   * Validate file structure conventions
   */
  private validateFileStructure(route: Readonly<RouteInfo>): void {
    if (!route.serviceFilePath) {
      return;
    }

    // Check if service is in correct directory
    if (!route.serviceFilePath.includes(this.config.requiredServiceDirectory)) {
      this.addError({
        code: 'INVALID_SERVICE_LOCATION',
        filePath: route.handlerFilePath,
        message: `Service file must be in ${this.config.requiredServiceDirectory} directory`,
        path: route.path,
        suggestion: `Move service to: ${this.config.requiredServiceDirectory}`,
        type: 'structure',
      });
    }

    // Validate service filename matches class name
    if (route.serviceClass) {
      const expectedFileName = this.getExpectedServiceFileName(
        route.serviceClass
      );
      if (!route.serviceFilePath.includes(expectedFileName)) {
        this.addWarning({
          code: 'MISMATCHED_SERVICE_FILENAME',
          filePath: route.handlerFilePath,
          message: 'Service filename should match class name convention',
          path: route.path,
          suggestion: `Expected filename: ${expectedFileName}`,
          type: 'naming',
        });
      }
    }
  }

  /**
   * Validate HTTP method consistency
   */
  private validateHttpMethodConsistency(route: Readonly<RouteInfo>): void {
    if (!(route.method && route.serviceMethod)) {
      return;
    }

    const method = route.method.toLowerCase();
    const serviceMethod = route.serviceMethod.toLowerCase();

    // Common patterns validation
    if (
      method === 'get' &&
      (serviceMethod.includes('create') ||
        serviceMethod.includes('update') ||
        serviceMethod.includes('delete'))
    ) {
      this.addWarning({
        code: 'HTTP_METHOD_MISMATCH',
        filePath: route.handlerFilePath,
        message: `GET method with ${route.serviceMethod} may indicate semantic mismatch`,
        path: route.path,
        suggestion: 'Consider using POST/PUT/DELETE for mutations',
        type: 'consistency',
      });
    }

    if (
      (method === 'post' || method === 'put') &&
      serviceMethod.startsWith('get')
    ) {
      this.addWarning({
        code: 'HTTP_METHOD_MISMATCH',
        filePath: route.handlerFilePath,
        message: `${method.toUpperCase()} method with ${route.serviceMethod} may indicate semantic mismatch`,
        path: route.path,
        suggestion: 'Consider using GET for queries',
        type: 'consistency',
      });
    }
  }

  /**
   * Validate route path formats
   */
  private validatePathFormats(route: Readonly<RouteInfo>): void {
    if (!(route.path && route.requestType)) {
      return;
    }

    if (route.requestType === 'HTTP') {
      // HTTP paths should start with / but not /trpc
      if (route.path.startsWith('/trpc')) {
        this.addError({
          code: 'INVALID_HTTP_PATH',
          filePath: route.handlerFilePath,
          message: 'HTTP route path should not start with /trpc',
          path: route.path,
          type: 'convention',
        });
      }
    } else if (route.requestType === 'tRPC') {
      // tRPC paths should start with /trpc/
      if (!route.path.startsWith('/trpc/')) {
        this.addError({
          code: 'INVALID_TRPC_PATH',
          filePath: route.handlerFilePath,
          message: 'tRPC route path must start with /trpc/',
          path: route.path,
          type: 'convention',
        });
      }

      // tRPC paths should use dot notation
      if (route.path.includes('/trpc/') && !route.path.includes('.')) {
        this.addWarning({
          code: 'MISSING_TRPC_DOT_NOTATION',
          filePath: route.handlerFilePath,
          message: 'tRPC route should use dot notation for method names',
          path: route.path,
          suggestion: 'Use format: /trpc/router.method',
          type: 'convention',
        });
      }
    }
  }

  /**
   * Validate individual route
   */
  private validateRoute(route: Readonly<RouteInfo>): void {
    this.validateRouteStructure(route);
    this.validateServiceNaming(route);
    this.validateFileStructure(route);
    this.validatePathFormats(route);
    this.validateConventions(route);
  }

  /**
   * Validate basic route structure
   */
  private validateRouteStructure(route: Readonly<RouteInfo>): void {
    // Allow empty string paths for root routes (handles both '' and '/' patterns)
    if (!route.path) {
      this.addError({
        code: 'MISSING_PATH',
        filePath: route.handlerFilePath,
        message: 'Route is missing path',
        type: 'structure',
      });
    }

    if (!route.requestType) {
      this.addError({
        code: 'MISSING_REQUEST_TYPE',
        filePath: route.handlerFilePath,
        message: 'Route is missing requestType (HTTP/tRPC)',
        path: route.path,
        type: 'structure',
      });
    }

    if (!(route.serviceClass && route.serviceMethod)) {
      this.addWarning({
        code: 'MISSING_SERVICE_INFO',
        filePath: route.handlerFilePath,
        message: 'Route is missing service class or method information',
        path: route.path,
        suggestion:
          'Ensure route uses createRouteHandler(ServiceClass, "methodName") pattern',
        type: 'convention',
      });
    }
  }

  /**
   * Validate service class naming conventions
   */
  private validateServiceNaming(route: Readonly<RouteInfo>): void {
    if (!(this.config.enforceServiceNaming && route.serviceClass)) {
      return;
    }

    // Check PascalCase + "Service" suffix
    if (!route.serviceClass.endsWith('Service')) {
      this.addError({
        code: 'INVALID_SERVICE_SUFFIX',
        filePath: route.handlerFilePath,
        message: `Service class "${route.serviceClass}" must end with "Service"`,
        path: route.path,
        suggestion: `Rename to "${route.serviceClass}Service"`,
        type: 'naming',
      });
    }

    // Check PascalCase format
    if (!PASCAL_CASE_REGEX.test(route.serviceClass)) {
      this.addError({
        code: 'INVALID_SERVICE_NAMING',
        filePath: route.handlerFilePath,
        message: `Service class "${route.serviceClass}" must be PascalCase`,
        path: route.path,
        suggestion: 'Use PascalCase format: MyServiceNameService',
        type: 'naming',
      });
    }

    // Validate service method naming
    if (
      route.serviceMethod &&
      !CAMEL_CASE_REGEX.test(route.serviceMethod) &&
      !route.serviceMethod.startsWith('_')
    ) {
      this.addWarning({
        code: 'INVALID_METHOD_NAMING',
        filePath: route.handlerFilePath,
        message: `Service method "${route.serviceMethod}" should be camelCase`,
        path: route.path,
        suggestion: 'Use camelCase format: myMethodName',
        type: 'naming',
      });
    }
  }

  /**
   * Validate tRPC procedure type consistency
   */
  private validateTrpcProcedureType(route: Readonly<RouteInfo>): void {
    if (!(route.type && route.serviceMethod)) {
      return;
    }

    const procedureType = route.type;
    const serviceMethod = route.serviceMethod.toLowerCase();

    if (
      procedureType === 'query' &&
      (serviceMethod.includes('create') ||
        serviceMethod.includes('update') ||
        serviceMethod.includes('delete'))
    ) {
      this.addWarning({
        code: 'TRPC_PROCEDURE_MISMATCH',
        filePath: route.handlerFilePath,
        message: `Query procedure with ${route.serviceMethod} may indicate semantic mismatch`,
        path: route.path,
        suggestion: 'Consider using mutation for side effects',
        type: 'consistency',
      });
    }

    if (procedureType === 'mutation' && serviceMethod.startsWith('get')) {
      this.addWarning({
        code: 'TRPC_PROCEDURE_MISMATCH',
        filePath: route.handlerFilePath,
        message: `Mutation procedure with ${route.serviceMethod} may indicate semantic mismatch`,
        path: route.path,
        suggestion: 'Consider using query for read operations',
        type: 'consistency',
      });
    }
  }
}

