    cacheAge: number;
    cached: boolean;
    validFor: number;
  } {
    const now = Date.now();
    const cacheAge = now - this.lastCacheTime;
    const validFor = Math.max(0, this.cacheValidityMs - cacheAge);

    return {
      cacheAge,
      cached: Boolean(this.projectCache),
      validFor,
    };
