import { Node } from 'ts-morph';
import { getProject, projectDir } from '../config';
import { extractHttpServiceMethod } from '../parsers/http-parser';
import {
  extractServiceMetadata,
  getServiceNameFromHandlerFile,
} from '../parsers/service-parser';
import type { RouteInfo } from '../types';

/**
 * Extract the HTTP method from initializer text
 */
const extractHttpMethod = (initializer: any): string => {
  if (!initializer) {
    return 'unknown';
  }

  const text = initializer.getText();
  if (text.includes('publicHttp.get')) {
    return 'get';
  }
  if (text.includes('publicHttp.post')) {
    return 'post';
  }
  if (text.includes('publicHttp.put')) {
    return 'put';
  }
  if (text.includes('publicHttp.delete')) {
    return 'delete';
  }
  if (text.includes('publicHttp.patch')) {
    return 'patch';
  }
  return 'unknown';
};

/**
 * Extract route path from property name node
 */
const extractRoutePath = (nameNode: any): string | null => {
  if (!(nameNode instanceof Node)) {
    return null;
  }
  if (Node.isStringLiteral(nameNode)) {
    return nameNode.getLiteralValue();
  }
  if (Node.isIdentifier(nameNode)) {
    return nameNode.getText();
  }
  return null;
};

/**
 * Process routes from an object literal expression
 */
const processRouteProperties = async (
  expression: any,
  handlerFilePath: string
): Promise<readonly RouteInfo[]> => {
  if (!(expression instanceof Node) || !Node.isObjectLiteralExpression(expression)) {
    globalThis.console.warn(`Export is not object literal in ${handlerFilePath}`);
    return [];
  }

  const routePromises = expression.getProperties().map(async (propertyNode: any) => {
    if (!(propertyNode instanceof Node) || !Node.isPropertyAssignment(propertyNode)) {
      return null;
    }
    const property = propertyNode;

    const nameNode = property.getNameNode();
    const routePath = extractRoutePath(nameNode);

    if (!routePath) {
      return null;
    }

    const method = extractHttpMethod(property.getInitializer());
    const serviceClass = getServiceNameFromHandlerFile(handlerFilePath);
    const serviceMethod = extractHttpServiceMethod(handlerFilePath, routePath);

    globalThis.console.log('HTTP service extraction:', {
      handlerFilePath,
      path: routePath,
      serviceClass,
      serviceMethod,
    });

    const { input, serviceFilePath } = await extractServiceMetadata(
      serviceClass,
      serviceMethod
    );

    return {
      handlerFilePath,
      input,
      method,
      output: undefined,
      path: routePath,
      requestType: 'HTTP',
      serviceClass,
      serviceFilePath,
      serviceMethod,
    } as RouteInfo;
  });

  return (await Promise.all(routePromises)).filter(
    (route): route is RouteInfo => route !== null
  );
};

/**
 * Extract all HTTP routes from the HTTP router
 */
export const getHttpRoutes = async (): Promise<RouteInfo[]> => {
  globalThis.console.log('Extracting HTTP routes...');

  const routes: RouteInfo[] = [];
  const project = getProject();
  const httpRouterPath = `${projectDir}/src/routers/http/index.ts`;
  const httpRouterFile = project.getSourceFile(httpRouterPath);

  if (!httpRouterFile) {
    globalThis.console.warn(`HTTP router file not found: ${httpRouterPath}`);
    return routes;
  }

  // Get imported route names from the HTTP router
  const importedRouteNames = httpRouterFile
    .getImportDeclarations()
    .map((importDecl: any) => importDecl.getDefaultImport()?.getText())
    .filter((name: any): name is string => name !== undefined);

  globalThis.console.log('Found HTTP route imports:', importedRouteNames);

  // Process each imported route file
  const filePromises = importedRouteNames.map(async routeName => {
    const handlerFilePath = `${projectDir}/src/routers/http/routes/${routeName.replace('Routes', '').toLowerCase()}.ts`;
    const handlerFile = project.getSourceFile(handlerFilePath);

    if (!handlerFile) {
      globalThis.console.warn(`Handler file not found: ${handlerFilePath}`);
      return [];
    }

    globalThis.console.log(`Processing HTTP routes from: ${handlerFilePath}`);

    const exportAssignment = handlerFile
      .getExportAssignments()
      .find((assignment: any) => !assignment.isExportEquals());

    if (!exportAssignment) {
      globalThis.console.warn(`No default export found in ${handlerFilePath}`);
      return [];
    }

    const localRoutes = await processRouteProperties(
      exportAssignment.getExpression() as Readonly<Node>,
      handlerFilePath
    );
    return localRoutes;
  });

  const allRoutes = await Promise.all(filePromises);
  for (const fileRoutes of allRoutes) {
    routes.push(...fileRoutes);
  }

  return routes;
};

