  ExpressNextFunction,
  ExpressResponse,
} from '../types/middlware';

import { allowedOrigins } from '../utils/cors';

export const allowedCsp = [...allowedOrigins];

export const cspMiddleware = (
  _req: any,
  res: any,
  next: any
) => {
  const mRes: ExpressResponse = res;
  const _mNext: ExpressNextFunction = next;

  let csp = '';
  for (const origin of allowedCsp) {
    csp += `default-src 'self'; script-src 'self' ${origin}; worker-src 'self' ${origin}; `;
  }

  csp = csp.trim();

  mRes.setHeader('Content-Security-Policy', csp);

  _mNext();
};
