  switch (type) {
    case 'any':
    case 'unknown': {
      return { default: defaultValue, description: 'Any value' };
    }
    case 'boolean': {
      return { default: defaultValue, type: 'boolean' };
    }
    case 'number': {
      return { default: defaultValue, type: 'number' };
    }
    case 'string': {
      return { default: defaultValue, type: 'string' };
